using Npgsql;
using ProgrammingTasks.Domain.Entities;
using ProgrammingTasks.Domain.Interfaces;

namespace ProgrammingTasks.Infrastructure;

public sealed class PostgreSqlTaskRepository(PostgreSqlConnectionSettings settings) : ITaskRepository
{
    private readonly string _connectionString = new NpgsqlConnectionStringBuilder { Host = settings.Host, Port = settings.Port, Database = settings.Database, Username = settings.Username, Password = settings.Password }.ConnectionString;
    public IReadOnlyList<ProgrammingTask> GetAll()
    {
        using var connection = new NpgsqlConnection(_connectionString); connection.Open(); using var command = connection.CreateCommand(); command.CommandText = "SELECT id,title,statement,solution_idea,polygon_url,prepared_for_codeforces,prepared_for_yandex,difficulty,note FROM programming_tasks ORDER BY id DESC"; using var reader = command.ExecuteReader(); var result = new List<ProgrammingTask>(); while (reader.Read()) result.Add(new ProgrammingTask { Id = reader.GetInt32(0), Title = reader.GetString(1), Statement = reader.GetString(2), SolutionIdea = reader.GetString(3), PolygonUrl = reader.IsDBNull(4) ? null : reader.GetString(4), PreparedForCodeforces = reader.GetBoolean(5), PreparedForYandexContest = reader.GetBoolean(6), Difficulty = reader.GetInt32(7), Note = reader.IsDBNull(8) ? null : reader.GetString(8) }); reader.Close(); foreach (var task in result) LoadLinks(connection, task); return result;
    }
    public void Save(ProgrammingTask task)
    {
        using var connection = new NpgsqlConnection(_connectionString); connection.Open(); using var command = connection.CreateCommand(); command.CommandText = task.Id == 0 ? "INSERT INTO programming_tasks(title,statement,solution_idea,polygon_url,prepared_for_codeforces,prepared_for_yandex,difficulty,note) VALUES(@title,@statement,@idea,@url,@cf,@yandex,@difficulty,@note) RETURNING id" : "UPDATE programming_tasks SET title=@title,statement=@statement,solution_idea=@idea,polygon_url=@url,prepared_for_codeforces=@cf,prepared_for_yandex=@yandex,difficulty=@difficulty,note=@note WHERE id=@id"; AddParameters(command, task); if (task.Id == 0) task.Id = Convert.ToInt32(command.ExecuteScalar()); else command.ExecuteNonQuery(); using var clear = connection.CreateCommand(); clear.CommandText = "DELETE FROM task_tags WHERE task_id=@id; DELETE FROM task_contests WHERE task_id=@id"; clear.Parameters.AddWithValue("id", task.Id); clear.ExecuteNonQuery(); foreach (var tag in task.Tags.Distinct(StringComparer.OrdinalIgnoreCase)) { using var link = connection.CreateCommand(); link.CommandText = "INSERT INTO tags(name) VALUES(@name) ON CONFLICT(name) DO UPDATE SET name=EXCLUDED.name RETURNING id"; link.Parameters.AddWithValue("name", tag); var tagId = Convert.ToInt32(link.ExecuteScalar()); using var relation = connection.CreateCommand(); relation.CommandText = "INSERT INTO task_tags(task_id,tag_id) VALUES(@task,@tag) ON CONFLICT DO NOTHING"; relation.Parameters.AddWithValue("task", task.Id); relation.Parameters.AddWithValue("tag", tagId); relation.ExecuteNonQuery(); } foreach (var contest in task.Contests.Distinct(StringComparer.OrdinalIgnoreCase)) { using var link = connection.CreateCommand(); link.CommandText = "INSERT INTO contests(name) VALUES(@name) ON CONFLICT(name) DO UPDATE SET name=EXCLUDED.name RETURNING id"; link.Parameters.AddWithValue("name", contest); var contestId = Convert.ToInt32(link.ExecuteScalar()); using var relation = connection.CreateCommand(); relation.CommandText = "INSERT INTO task_contests(task_id,contest_id) VALUES(@task,@contest) ON CONFLICT DO NOTHING"; relation.Parameters.AddWithValue("task", task.Id); relation.Parameters.AddWithValue("contest", contestId); relation.ExecuteNonQuery(); } ApplicationLogger.Info($"POSTGRES: задача сохранена '{task.Title}'");
    }
    public void Delete(int id) { using var connection = new NpgsqlConnection(_connectionString); connection.Open(); using var command = connection.CreateCommand(); command.CommandText = "DELETE FROM programming_tasks WHERE id=@id"; command.Parameters.AddWithValue("id", id); command.ExecuteNonQuery(); ApplicationLogger.Info($"POSTGRES: задача удалена Id={id}"); }
    private static void LoadLinks(NpgsqlConnection connection, ProgrammingTask task) { using var tags = connection.CreateCommand(); tags.CommandText = "SELECT t.name FROM tags t JOIN task_tags l ON l.tag_id=t.id WHERE l.task_id=@id"; tags.Parameters.AddWithValue("id", task.Id); using var tagReader = tags.ExecuteReader(); while (tagReader.Read()) task.Tags.Add(tagReader.GetString(0)); tagReader.Close(); using var contests = connection.CreateCommand(); contests.CommandText = "SELECT c.name FROM contests c JOIN task_contests l ON l.contest_id=c.id WHERE l.task_id=@id"; contests.Parameters.AddWithValue("id", task.Id); using var contestReader = contests.ExecuteReader(); while (contestReader.Read()) task.Contests.Add(contestReader.GetString(0)); }
    private static void AddParameters(NpgsqlCommand command, ProgrammingTask task) { command.Parameters.AddWithValue("title", task.Title); command.Parameters.AddWithValue("statement", task.Statement); command.Parameters.AddWithValue("idea", task.SolutionIdea); command.Parameters.AddWithValue("url", (object?)task.PolygonUrl ?? DBNull.Value); command.Parameters.AddWithValue("cf", task.PreparedForCodeforces); command.Parameters.AddWithValue("yandex", task.PreparedForYandexContest); command.Parameters.AddWithValue("difficulty", task.Difficulty); command.Parameters.AddWithValue("note", (object?)task.Note ?? DBNull.Value); if (task.Id != 0) command.Parameters.AddWithValue("id", task.Id); }
}
